('b0000000-0000-0000-0000-000000000101', 2, 'Rotting tomatoes is a chemical change because new substances are formed.', 'True', 'False', 'True', 'Rotting involves decomposition, producing new substances.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Crushing chunks of ice is a chemical change because its shape changes.', 'True', 'False', 'False', 'Crushing ice only changes its size and shape. The substance remains water.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'A chemical change produces one or more new substances.', 'True', 'False', 'True', 'The chemical composition changes during a chemical change.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Photosynthesis is a physical change because plants only absorb sunlight.', 'True', 'False', 'False', 'Photosynthesis is a chemical reaction that produces glucose and oxygen.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Gas bubbles produced when vinegar reacts with baking soda are evidence of a chemical reaction.', 'True', 'False', 'True', 'The bubbles are carbon dioxide gas formed during the reaction.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Curdling of milk is considered evidence of gas formation.', 'True', 'False', 'False', 'It is evidence of precipitate formation, where solid curds are produced.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'If a container becomes hot after quicklime is mixed with water, a chemical reaction has occurred.', 'True', 'False', 'True', 'The release of heat indicates an exothermic chemical reaction.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Simply cutting paper is evidence that a chemical reaction occurred.', 'True', 'False', 'False', 'Cutting only changes the paper''s shape, not its composition.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'When two clear liquids produce a solid that settles at the bottom, a precipitate has formed.', 'True', 'False', 'True', 'A precipitate is an insoluble solid formed during a reaction.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Reactants are written on the right side of a chemical equation.', 'True', 'False', 'False', 'Reactants are written on the left side of the reaction arrow.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Products are the new substances formed during a chemical reaction.', 'True', 'False', 'True', 'Products appear on the right side of the chemical equation.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'The symbol (aq) means the substance is in the gaseous state.', 'True', 'False', 'False', '(aq) means the substance is dissolved in water.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'The symbol Δ above a reaction arrow means heat is supplied to the reaction.', 'True', 'False', 'True', 'Delta (Δ) indicates that heating is required.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'A downward arrow (↓) beside a product indicates that a gas is released.', 'True', 'False', 'False', 'A downward arrow indicates the formation of a precipitate.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'The plus (+) sign in a chemical equation means the substances are mixed or react together.', 'True', 'False', 'True', 'It is read as "reacts with" or "and."', true),
('b0000000-0000-0000-0000-000000000101', 2, 'A combination reaction follows the general equation A + B → AB.', 'True', 'False', 'True', 'Two or more reactants combine to form a single product.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'The reaction 2Na + Cl₂ → 2NaCl is an example of decomposition.', 'True', 'False', 'False', 'It is a combination (synthesis) reaction because two reactants form one product.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'The reaction CaCO₃ → CaO + CO₂ is a decomposition reaction.', 'True', 'False', 'True', 'One compound breaks down into two simpler substances.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'The general equation AB → A + B represents a combination reaction.', 'True', 'False', 'False', 'It represents decomposition.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'In a single displacement reaction, one element replaces another element in a compound.', 'True', 'False', 'True', 'This is the defining characteristic of single displacement.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Double displacement reactions involve one element replacing another element.', 'True', 'False', 'False', 'They involve two compounds exchanging ions.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'The reaction AgNO₃ + NaCl → AgCl + NaNO₃ is a double displacement reaction.', 'True', 'False', 'True', 'The ions exchange partners to form new compounds.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Oxygen gas is always a reactant in combustion reactions.', 'True', 'False', 'True', 'Combustion requires oxygen to occur.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Combustion of hydrocarbons always produces salt and water.', 'True', 'False', 'False', 'It produces carbon dioxide and water.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Neutralization reactions produce salt and water.', 'True', 'False', 'True', 'They occur when an acid reacts with a base.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Neutralization is classified as a special type of combination reaction.', 'True', 'False', 'False', 'It is a special type of double displacement reaction.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Melting wax is an example of a physical change.', 'True', 'False', 'True', 'Only the state changes; no new substance is formed.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Salt dissolving in water is evidence of a chemical reaction.', 'True', 'False', 'False', 'Dissolving salt is a physical change.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'In the equation Mg + O₂ → MgO, magnesium oxide is the product.', 'True', 'False', 'True', 'Products are found on the right side of the arrow.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Fuel reacting with oxygen to produce carbon dioxide and water is called combustion.', 'True', 'False', 'True', 'This is the general form of a combustion reaction.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'The arrow (→) in a chemical equation means "yields" or "produces."', 'True', 'False', 'True', 'It separates reactants from products.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'The reaction 2H₂O₂ → 2H₂O + O₂ is a synthesis reaction.', 'True', 'False', 'False', 'It is a decomposition reaction because one compound breaks apart.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Double displacement reactions involve the exchange of ions between two compounds.', 'True', 'False', 'True', 'The ions switch partners to form new compounds.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Iron reacting with sulfur to form iron sulfide is an example of synthesis.', 'True', 'False', 'True', 'Two reactants combine to form one compound.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'The symbol (g) or an upward arrow (↑) indicates that a solid has formed.', 'True', 'False', 'False', 'It indicates that a gas is produced. TRUE OR FALSE : topic 3 :Acids, Bases, and Salts', true),
('b0000000-0000-0000-0000-000000000101', 2, 'All acids have a sour taste and turn blue litmus paper red.', 'True', 'False', 'True', 'These are characteristic properties of acids.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Bases turn blue litmus paper red.', 'True', 'False', 'False', 'Bases turn red litmus paper blue.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Pure water has a pH of 7, making it neutral.', 'True', 'False', 'True', 'A pH of 7 indicates a neutral solution.', true),
