('b0000000-0000-0000-0000-000000000101', 2, 'Bases release hydrogen ions (H⁺) in water.', 'True', 'False', 'False', 'Bases release hydroxide ions (OH⁻).', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Sodium chloride (NaCl) is the chemical name for common table salt.', 'True', 'False', 'True', 'Sodium chloride is a neutral salt commonly used as table salt.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Hydrochloric acid found in the stomach has the formula H₂SO₄.', 'True', 'False', 'False', 'The correct formula is HCl.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Sodium hydroxide (NaOH) is a strong base commonly known as lye.', 'True', 'False', 'True', 'NaOH is also called caustic soda or lye.', true),
