('b0000000-0000-0000-0000-000000000101', 2, 'Turmeric is considered a natural acid-base indicator.', 'True', 'False', 'True', 'Turmeric changes color in basic solutions.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'A solution with a pH of 7 is acidic.', 'True', 'False', 'False', 'A pH of 7 is neutral.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Vinegar contains acetic acid.', 'True', 'False', 'True', 'Acetic acid gives vinegar its sour taste.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Milk of magnesia contains sodium hydroxide.', 'True', 'False', 'False', 'It contains magnesium hydroxide, Mg(OH)₂.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Blue litmus paper remains blue when placed in a basic solution.', 'True', 'False', 'True', 'Bases do not change the color of blue litmus paper.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Hydrochloric acid, vinegar, and calamansi juice are all examples of acids.', 'True', 'False', 'True', 'All three exhibit acidic properties.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Sodium hydroxide, bleach, and milk of magnesia are examples of bases.', 'True', 'False', 'True', 'These substances are classified as bases.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Antacids relieve hyperacidity because they are weak acids.', 'True', 'False', 'False', 'Antacids are mild bases that neutralize excess stomach acid.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'A solution with a pH of 4 is acidic.', 'True', 'False', 'True', 'Any pH below 7 is acidic.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'A solution with a pH of 11 is acidic.', 'True', 'False', 'False', 'A pH above 7 indicates a basic or alkaline solution.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Among pH 1, pH 3, and pH 6, pH 6 is the weakest acid.', 'True', 'False', 'True', 'It is closest to neutral (pH 7).', true),
('b0000000-0000-0000-0000-000000000101', 2, 'A neutralization reaction produces salt and water from an acid and a base.', 'True', 'False', 'True', 'This is the general equation for neutralization.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Turmeric turns reddish-brown when exposed to a base such as soap.', 'True', 'False', 'True', 'This color change indicates the presence of a base.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Onion and vanilla are examples of synthetic indicators.', 'True', 'False', 'False', 'They are olfactory indicators because they change smell in acids and bases.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Tooth enamel begins to dissolve when the pH in the mouth drops below 5.5.', 'True', 'False', 'True', 'Low pH increases the risk of tooth decay.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Sodium carbonate (Na₂CO₃) forms an acidic solution in water.', 'True', 'False', 'False', 'It forms a basic solution.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Ammonium chloride (NH₄Cl) forms an acidic solution when dissolved in water .', 'True', 'False', 'True', 'NH₄Cl is an acidic salt.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Dry hydrogen chloride gas changes dry blue litmus paper to red immediately.', 'True', 'False', 'False', 'Water is needed for HCl to release hydrogen ions.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Each pH unit represents a tenfold change in hydrogen ion concentration.', 'True', 'False', 'True', 'The pH scale is logarithmic.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'In the order pH 2, pH 6, pH 7, pH 9, and pH 12, pH 12 is the strongest acid.', 'True', 'False', 'False', 'pH 12 is the strongest base, while pH 2 is the strongest acid.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Sodium chloride (NaCl) is produced from a strong acid and a strong base and is generally neutral.', 'True', 'False', 'True', 'HCl reacts with NaOH to produce NaCl and water.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Acidic and basic solutions can conduct electricity because they contain mobile ions.', 'True', 'False', 'True', 'The movement of ions allows electric current to flow.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'When diluting concentrated acid, water should always be poured into the acid.', 'True', 'False', 'False', 'Acid should always be added slowly to water to prevent splashing.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Acetic acid (CH₃COOH) is the weak acid present in vinegar.', 'True', 'False', 'True', 'It is responsible for vinegar''s acidic properties.', true),
