('b0000000-0000-0000-0000-000000000101', 2, 'Reactants are written on the left side of a chemical equation.', 'True', 'False', 'True', 'Reactants are the starting substances before the reaction occurs.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'Products are found on the left side of the reaction arrow.', 'True', 'False', 'False', 'Products are written on the right side of the arrow because they are formed after the reaction.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'The symbol (aq) means a substance is dissolved in water.', 'True', 'False', 'True', '"Aqueous" means the substance is in a water solution.', true),
