('b0000000-0000-0000-0000-000000000101', 2, 'The symbol (g) indicates that a substance is in the gaseous state.', 'True', 'False', 'True', '(g) is the standard symbol for gases.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'The Law of Conservation of Mass states that mass can be created during a chemical reaction.', 'True', 'False', 'False', 'Mass is neither created nor destroyed; the total mass of reactants equals the total mass of products.', true),
('b0000000-0000-0000-0000-000000000101', 2, 'The arrow (→) in a chemical equation is read as "yields" or "produces."', 'True', 'False', 'True', 'It separates the reactants from the products.', true),
